    i = s.index('=', s.index('_d["team"]')); d = json.loads(s[i + 1:].rstrip().rstrip(';'))
    have = {x['key']: x for x in d['docs'] if x['key'] != 'jeerachart'}
    for k, v in NEW.items():
        have[k] = {'key': k, 'photo': v['photo'], **v[L]}
    d['docs'] = [have[k] for k in ORDER]
    open(p, 'w', encoding='utf-8').write(s[:i + 1] + json.dumps(d, ensure_ascii=False) + ';\n')
    print(L, [x['key'] for x in d['docs']])
